static std::string cmd = "gcu";
static int err(const std::string& s){ std::cerr << cmd << ": " << s << "\n"; return 1; }
static std::string basename_s(std::string s){ while(s.size()>1 && s.back()=='/') s.pop_back(); auto p=s.find_last_of('/'); return p==std::string::npos?s:s.substr(p+1); }
static std::string dirname_s(std::string s){ while(s.size()>1 && s.back()=='/') s.pop_back(); auto p=s.find_last_of('/'); if(p==std::string::npos)return "."; if(p==0)return "/"; return s.substr(0,p); }
static bool number(const std::string&s,long long&v){try{size_t n=0; v=std::stoll(s,&n,0); return n==s.size();}catch(...){return false;}}
static std::vector<std::string> split_lines(const std::string&s){std::vector<std::string>v; std::istringstream in(s); std::string l; while(std::getline(in,l))v.push_back(l); if(!s.empty()&&s.back()=='\n'){} return v;}
static bool read_all(const std::string&name,std::string&out){if(name=="-"){std::ostringstream ss; ss<<std::cin.rdbuf(); out=ss.str(); return !std::cin.bad();} std::ifstream f(name,std::ios::binary); if(!f)return false; std::ostringstream ss; ss<<f.rdbuf(); out=ss.str(); return !f.bad();}
static bool write_file(const std::string&p,const std::string&s,bool append=false){std::ofstream f(p,std::ios::binary|(append?std::ios::app:std::ios::trunc)); if(!f)return false; f.write(s.data(),(std::streamsize)s.size()); return bool(f);}
static std::string visible(const std::string&s,bool tabs,bool ends,bool all){std::string o; for(unsigned char c:s){if(c=='\t'&&tabs)o+="^I";else if(c=='\r'&&ends)o+="^M";else if(c<32&&c!='\n'&&c!='\t') {o+='^';o+=char(c+64);} else if(c==127)o+="^?"; else if(all&&c>=128){o+="M-";o+=char(c&127);} else o+=char(c);} return o;}
static int cmd_cowf(const Args&a){
    bool nb=false,n=false,e=false,t=false,v=false,s=false;std::vector<std::string>files;bool options=true;
    for(size_t i=0;i<a.size();++i){const auto&x=a[i];if(options&&x=="--"){options=false;continue;}if(options&&x=="-sa"){v=e=t=true;}else if(options&&x=="-numb")nb=true;else if(options&&x=="-eqve")v=e=true;else if(options&&x=="-she")e=true;else if(options&&x=="-num")n=true;else if(options&&x=="-squb")s=true;else if(options&&x=="-eqvt")v=t=true;else if(options&&x=="-T")t=true;else if(options&&x=="-ipo"){}else if(options&&x=="-v")v=true;else if(options&&x=="--help"){std::cout<<"Usage: cowf [-sa] [-num|-numb] [-she] [-T] [-v] [-squb] [FILE...]\n";return 0;}else if(options&&x.size()>1&&x[0]=='-')return err("unknown option '"+x+"'");else files.push_back(x);}
    if(files.empty())files.push_back("-");long long line=1;bool lastblank=false;int rc=0;
    for(const auto&f:files){std::ifstream file;std::istream*in=&std::cin;if(f!="-"){file.open(f,std::ios::binary);if(!file){err("cannot open '"+f+"': "+std::strerror(errno));rc=1;continue;}in=&file;}std::string l;
        while(std::getline(*in,l)){bool newline=!in->eof();bool blank=l.empty();if(!(s&&blank&&lastblank)){if(nb){if(!blank)std::cout<<std::setw(6)<<line++<<"\t";}else if(n)std::cout<<std::setw(6)<<line++<<"\t";std::cout<<visible(l,t,e,v);if(e)std::cout<<"$";if(newline)std::cout<<"\n";}lastblank=blank;}
        if(in->bad()){err("read error on '"+f+"'");rc=1;}
    }
    if(!std::cout)return err("write error");return rc;
}
static int cmd_fcow(const Args&a){
    std::string sep="\n";bool before=false,regex_mode=false,options=true;std::vector<std::string>files;
    for(size_t i=0;i<a.size();++i){if(options&&a[i]=="--"){options=false;continue;}if(options&&a[i]=="-bef")before=true;else if(options&&a[i]=="-rex")regex_mode=true;else if(options&&a[i]=="-s"){if(++i>=a.size())return err("-s requires a separator");sep=a[i];}else if(options&&a[i]=="--help"){std::cout<<"Usage: fcow [-bef] [-rex] [-s SEPARATOR] [FILE...]\n";return 0;}else files.push_back(a[i]);}
    if(files.empty())files.push_back("-");int rc=0;
    for(const auto&f:files){std::string d;if(!read_all(f,d)){err("cannot read '"+f+"'");rc=1;continue;}if(d.empty())continue;std::vector<std::string>records,seps;bool trailing=false;std::string trailing_sep=sep;
        if(regex_mode){try{std::regex re(sep);size_t pos=0;for(std::sregex_iterator it(d.begin(),d.end(),re),last;it!=last;++it){auto m=*it;size_t p=(size_t)m.position(),n=(size_t)m.length();records.push_back(d.substr(pos,p-pos));seps.push_back(m.str());pos=p+n;}trailing=pos==d.size()&&!seps.empty();if(trailing)trailing_sep=seps.back();records.push_back(d.substr(pos));}catch(const std::regex_error&){return err("invalid separator regular expression");}}
        else{if(sep.empty())return err("separator cannot be empty");size_t pos=0;while(pos<=d.size()){auto q=d.find(sep,pos);if(q==std::string::npos){records.push_back(d.substr(pos));break;}records.push_back(d.substr(pos,q-pos));seps.push_back(sep);pos=q+sep.size();}trailing=!seps.empty()&&d.size()>=sep.size()&&d.compare(d.size()-sep.size(),sep.size(),sep)==0;}
        if(trailing){if(!records.empty()&&records.back().empty())records.pop_back();if(!seps.empty())seps.pop_back();}
        std::reverse(records.begin(),records.end());std::reverse(seps.begin(),seps.end());for(size_t i=0;i<records.size();++i){if(before){if(i<seps.size())std::cout<<seps[i];std::cout<<records[i];}else{std::cout<<records[i];if(i+1<records.size()&&i<seps.size())std::cout<<seps[i];}}if(trailing&&!before)std::cout<<trailing_sep;
    }
    return rc;
}
static int cmd_numl(const Args&a){bool nonblank=true;long long n=1;std::vector<std::string>files;for(size_t i=0;i<a.size();++i){if(a[i]=="--help"){std::cout<<"Usage: numl [OPTIONS] [FILE...]\n";return 0;}else if(a[i]=="-num")nonblank=false;else if(a[i]=="-non")nonblank=true;else if(a[i]=="-nal")nonblank=false;else if(a[i]=="-bsty"||a[i]=="-dnon"){if(i+1<a.size()&&a[i+1][0]!='-')++i;}else files.push_back(a[i]);}if(files.empty())files.push_back("-");for(auto&f:files){std::string d;if(!read_all(f,d))return err("cannot read '"+f+"'");std::istringstream in(d);std::string l;while(std::getline(in,l)){if(!nonblank||!l.empty())std::cout<<std::setw(6)<<n++<<"\t";else std::cout<<"       \t";std::cout<<l<<"\n";}}return 0;}
static int cmd_wfof(const Args&a){int base=8;bool noaddr=false,chars=false,dups=false;std::vector<std::string>files;long long limit=-1;for(size_t i=0;i<a.size();++i){auto x=a[i];if(x=="-dec")base=10;else if(x=="-oct")base=8;else if(x=="-hex")base=16;else if(x=="-none")noaddr=true;else if(x=="-char")chars=true;else if(x=="-odup")dups=true;else if(x=="-nchar"){if(++i>=a.size()||!number(a[i],limit)||limit<0)return err("invalid -nchar value");}else if(x=="-rad"){if(++i>=a.size())return err("-rad requires a base");if(a[i]=="d")base=10;else if(a[i]=="o")base=8;else if(a[i]=="x")base=16;else return err("base must be d, o, or x");}else if(x=="--help"){std::cout<<"Usage: wfof [-dec|-oct|-hex] [-none] [-char] [FILE...]\n";return 0;}else if(x.size()>1&&x[0]=='-')return err("unsupported option '"+x+"'");else files.push_back(x);}if(files.empty())files.push_back("-");unsigned long long offset=0;std::string previous;for(auto&f:files){std::string d;if(!read_all(f,d))return err("cannot read '"+f+"'");if(limit>=0&&d.size()>(size_t)limit)d.resize((size_t)limit);for(size_t i=0;i<d.size();i+=16){std::string row=d.substr(i,std::min<size_t>(16,d.size()-i));if(dups&&row==previous){if(i==0||i+16<d.size())std::cout<<"*\n";previous=row;continue;}if(!noaddr)std::cout<<std::setw(7)<<std::setfill('0')<<std::oct<<offset<<std::setfill(' ')<<" ";if(chars){for(unsigned char c:row)std::cout<<(std::isprint(c)?char(c):'.');}else{for(unsigned char c:row)std::cout<<std::setw(base==16?3:4)<<std::setfill('0')<<std::setbase(base)<<(unsigned)c<<std::setfill(' ')<<" ";}std::cout<<"\n";offset+=row.size();previous=row;}}if(!noaddr)std::cout<<std::setw(7)<<std::setfill('0')<<std::oct<<offset<<std::setfill(' ')<<"\n";return 0;}
static const char b64chars[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static std::string b64enc(const std::string&in){std::string o;unsigned val=0;int bits=-6;for(unsigned char c:in){val=(val<<8)+c;bits+=8;while(bits>=0){o.push_back(b64chars[(val>>bits)&63]);bits-=6;}}if(bits>-6)o.push_back(b64chars[((val<<8)>>(bits+8))&63]);while(o.size()%4)o.push_back('=');return o;}
static std::string b64dec(const std::string&in){std::array<int,256>t;t.fill(-1);for(int i=0;i<64;i++)t[(unsigned char)b64chars[i]]=i;std::string o;unsigned val=0;int bits=-8;for(unsigned char c:in){if(c=='='||std::isspace(c))continue;if(t[c]<0)throw std::runtime_error("invalid base64 input");val=(val<<6)+t[c];bits+=6;if(bits>=0){o.push_back(char((val>>bits)&255));bits-=8;}}return o;}
static std::string b32enc(const std::string&in){static const char*t="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";std::string o;unsigned acc=0;int bits=0;for(unsigned char c:in){acc=(acc<<8)|c;bits+=8;while(bits>=5){bits-=5;o+=t[(acc>>bits)&31];}}if(bits)o+=t[(acc<<(5-bits))&31];while(o.size()%8)o+='=';return o;}
static std::string b32dec(const std::string&in){std::string o;unsigned acc=0;int bits=0;for(unsigned char c:in){if(c=='='||std::isspace(c))continue;c=std::toupper(c);int v=c>='A'&&c<='Z'?c-'A':c>='2'&&c<='7'?c-'2'+26:-1;if(v<0)throw std::runtime_error("invalid base32 input");acc=(acc<<5)|v;bits+=5;if(bits>=8){bits-=8;o+=char((acc>>bits)&255);}}return o;}
static int cmd_base(const Args&a){bool dec=false;std::string mode=cmd;std::vector<std::string>files;for(auto&x:a){if(x=="-d"||x=="--decode")dec=true;else if(x=="--help"){std::cout<<"Usage: "<<cmd<<" [--decode] [FILE]\n";return 0;}else files.push_back(x);}if(files.size()>1)return err("too many input files");std::string d;if(files.empty())d.assign(std::istreambuf_iterator<char>(std::cin),{});else if(!read_all(files[0],d))return err("cannot read input");try{std::string o;if(mode=="b32")o=dec?b32dec(d):b32enc(d);else o=dec?b64dec(d):b64enc(d);std::cout.write(o.data(),o.size());if(!dec)std::cout<<"\n";return 0;}catch(const std::exception&e){return err(e.what());}}
static int cmd_bnc(const Args&a){bool dec=false;std::string mode="base64";std::vector<std::string>f;for(size_t i=0;i<a.size();++i){if(a[i]=="-d"||a[i]=="--decode")dec=true;else if(a[i]=="--base64")mode="base64";else if(a[i]=="--base32")mode="base32";else if(a[i]=="--help"){std::cout<<"Usage: bnc [--base64|--base32] [--decode] [FILE]\n";return 0;}else f.push_back(a[i]);}std::string d;if(f.empty())d.assign(std::istreambuf_iterator<char>(std::cin),{});else if(f.size()==1){if(!read_all(f[0],d))return err("cannot read input");}else return err("too many input files");try{auto o=mode=="base32"?(dec?b32dec(d):b32enc(d)):(dec?b64dec(d):b64enc(d));std::cout.write(o.data(),o.size());if(!dec)std::cout<<"\n";return 0;}catch(const std::exception&e){return err(e.what());}}
static int cmd_rff(const Args&a){size_t width=75;std::string prefix;std::vector<std::string>files;for(size_t i=0;i<a.size();++i){if(a[i]=="-wid"||a[i]=="-gol"){if(++i>=a.size())return err("width required");long long n;if(!number(a[i],n)||n<1||n>100000)return err("invalid width");width=(size_t)n;}else if(a[i]=="-prefx"){if(++i>=a.size())return err("prefix required");prefix=a[i];}else if(a[i]=="--help"){std::cout<<"Usage: rff [-wid N] [-prefx PREFIX] [FILE...]\n";return 0;}else if(a[i].size()>1&&a[i][0]=='-')return err("option '"+a[i]+"' is not implemented or needs a definition");else files.push_back(a[i]);}if(files.empty())files.push_back("-");int rc=0;bool previous_blank=false;for(const auto&f:files){std::string d;if(!read_all(f,d)){err("cannot read '"+f+"'");rc=1;continue;}std::istringstream in(d);std::string line;std::vector<std::string>words;auto flush=[&](){if(words.empty())return;std::string out;for(const auto&w:words){if(!out.empty()&&out.size()+1+w.size()>width){std::cout<<prefix<<out<<"\n";out.clear();}if(!out.empty())out+=' ';out+=w;}std::cout<<prefix<<out<<"\n";words.clear();};while(std::getline(in,line)){if(line.find_first_not_of(" \t\r")==std::string::npos){flush();if(!previous_blank)std::cout<<"\n";previous_blank=true;continue;}previous_blank=false;std::istringstream ws(line);std::string w;while(ws>>w)words.push_back(w);}flush();}return rc;}
static int cmd_warp(const Args&a){size_t width=80;bool bytes=false,chars=false,spaces=false;std::vector<std::string>files;for(size_t i=0;i<a.size();++i){if(a[i]=="-bytes")bytes=true;else if(a[i]=="-chars")chars=true;else if(a[i]=="-spacs")spaces=true;else if(a[i]=="-wid"){if(++i>=a.size())return err("width required");long long n;if(!number(a[i],n)||n<1||n>100000)return err("invalid width");width=(size_t)n;}else if(a[i]=="--help"){std::cout<<"Usage: warp [-bytes|-chars] [-spacs] [-wid N] [FILE...]\n";return 0;}else files.push_back(a[i]);}if(bytes&&chars)return err("choose either -bytes or -chars");if(files.empty())files.push_back("-");int rc=0;for(const auto&f:files){std::string d;if(!read_all(f,d)){err("cannot read '"+f+"'");rc=1;continue;}std::istringstream in(d);std::string line;while(std::getline(in,line)){std::vector<size_t>bounds{0};if(chars){for(size_t i=0;i<line.size();){unsigned char c=(unsigned char)line[i];size_t n=c<0x80?1:(c&0xe0)==0xc0?2:(c&0xf0)==0xe0?3:(c&0xf8)==0xf0?4:1;i=std::min(line.size(),i+n);bounds.push_back(i);}}else for(size_t i=1;i<=line.size();++i)bounds.push_back(i);size_t total=bounds.size()-1,pos=0;while(pos<total){size_t end=std::min(total,pos+width);if(spaces&&end<total){for(size_t q=end;q>pos;--q){size_t at=bounds[q-1];if(at<line.size()&&line[at]==' '){end=q-1;break;}}if(end==pos)end=std::min(total,pos+width);}std::cout<<line.substr(bounds[pos],bounds[end]-bounds[pos]);if(end<total)std::cout<<"\n";pos=end;while(spaces&&pos<total&&line[bounds[pos]]==' ')++pos;}std::cout<<"\n";}}return rc;}
static int cmd_headtail(const Args&a,bool tail){long long n=10;bool follow=false,options=true;std::vector<std::string>files;for(size_t i=0;i<a.size();++i){const auto&x=a[i];if(options&&x=="--"){options=false;continue;}if(options&&(x=="-f"||x=="--follow")){if(!tail)return err("follow mode is only supported by fend");follow=true;}else if(options&&x=="-n"){if(++i>=a.size()||!number(a[i],n)||n<0)return err("invalid line count");}else if(options&&x.size()>2&&x.substr(0,2)=="-n"){if(!number(x.substr(2),n)||n<0)return err("invalid line count");}else if(options&&x=="--help"){std::cout<<"Usage: "<<cmd<<" [-n N] [FILE...]"<<(tail?" [-f]":"")<<"\n";return 0;}else files.push_back(x);}if(files.empty())files.push_back("-");if(follow&&(files.size()!=1||files[0]=="-"))return err("follow mode requires exactly one regular file");int rc=0;std::streamoff offset=0;for(const auto&f:files){std::string d;if(!read_all(f,d)){err("cannot read '"+f+"'");rc=1;continue;}if(follow)offset=(std::streamoff)d.size();auto lines=split_lines(d);size_t start=tail?(lines.size()>(size_t)n?lines.size()-(size_t)n:0):0;size_t finish=tail?lines.size():std::min(lines.size(),(size_t)n);for(size_t j=start;j<finish;++j){std::cout<<lines[j]<<"\n";}}if(rc)return rc;if(!follow)return std::cout?0:1;std::ifstream f(files[0],std::ios::binary);if(!f)return err("cannot reopen '"+files[0]+"'");f.seekg(offset);if(!f)return err("cannot seek follow position");std::array<char,65536>b{};for(;;){f.read(b.data(),b.size());auto got=f.gcount();if(got>0){std::cout.write(b.data(),got);std::cout.flush();if(!std::cout)return 1;}else{if(f.bad())return err("follow read error");f.clear();usleep(200000);}}}
static int cmd_wc(const Args&a){bool l=false,w=false,c=false,m=false;std::vector<std::string>f;for(auto&x:a){if(x=="-l")l=true;else if(x=="-w")w=true;else if(x=="-c")c=true;else if(x=="-m")m=true;else if(x.size()>2&&x[0]=='-'&&x[1]!='-'){for(size_t i=1;i<x.size();++i){if(x[i]=='l')l=true;else if(x[i]=='w')w=true;else if(x[i]=='c')c=true;else if(x[i]=='m')m=true;else return err("unknown option");}}else if(x=="--help"){std::cout<<"Usage: wcnt [-lwmc] [FILE...]\n";return 0;}else f.push_back(x);}if(!l&&!w&&!c&&!m)l=w=c=true;if(f.empty())f.push_back("-");for(auto&name:f){std::string d;if(!read_all(name,d))return err("cannot read '"+name+"'");long long lines=std::count(d.begin(),d.end(),'\n'),words=0;bool in=false;for(unsigned char ch:d){if(std::isspace(ch))in=false;else if(!in){++words;in=true;}}if(l)std::cout<<std::setw(8)<<lines<<" ";if(w)std::cout<<std::setw(8)<<words<<" ";if(c)std::cout<<std::setw(8)<<d.size()<<" ";if(m)std::cout<<std::setw(8)<<d.size()<<" ";std::cout<<name<<"\n";}return 0;}
static int cmd_see(const Args&a){bool all=false,longf=false,recursive=false,options=true;std::vector<std::string>paths;for(const auto&x:a){if(options&&x=="--"){options=false;continue;}if(options&&(x=="-a"||x=="--all"))all=true;else if(options&&(x=="-l"||x=="--long"))longf=true;else if(options&&(x=="-R"||x=="--recursive"))recursive=true;else if(options&&x=="--help"){std::cout<<"Usage: see [-alR] [FILE...]\n";return 0;}else if(options&&x.size()>2&&x[0]=='-'&&x[1]!='-'){for(size_t i=1;i<x.size();++i){if(x[i]=='a')all=true;else if(x[i]=='l')longf=true;else if(x[i]=='R')recursive=true;else return err("unknown option ' "+x+"'");}}else paths.push_back(x);}if(paths.empty())paths.push_back(".");for(auto&p:paths){std::error_code ec;if(fs::is_directory(p,ec)){if(paths.size()>1)std::cout<<p<<":\n";if(recursive){for(auto it=fs::recursive_directory_iterator(p,ec);it!=fs::recursive_directory_iterator();it.increment(ec)){auto n=it->path().filename().string();if(all||n.empty()||n[0]!='.')std::cout<<it->path().string()<<"\n";}}else{std::vector<fs::directory_entry>v;for(auto&x:fs::directory_iterator(p,ec)){auto n=x.path().filename().string();if(all||n.empty()||n[0]!='.')v.push_back(x);}std::sort(v.begin(),v.end(),[](auto&x,auto&y){return x.path().filename()<y.path().filename();});for(auto&x:v){if(longf){struct stat st{};::stat(x.path().c_str(),&st);std::cout<<((S_ISDIR(st.st_mode))?'d':'-')<<std::oct<<((st.st_mode&0777))<<std::dec<<" "<<st.st_size<<" ";}std::cout<<x.path().filename().string()<<"\n";}}}else{struct stat st{};if(::stat(p.c_str(),&st)<0)return err("cannot access '"+p+"'");if(longf)std::cout<<((S_ISDIR(st.st_mode))?'d':'-')<<std::oct<<(st.st_mode&0777)<<std::dec<<" "<<st.st_size<<" ";std::cout<<p<<"\n";}}return 0;}
