    if(cmd=="huh"||cmd=="usrs"){std::set<std::string>users;if(cmd=="huh")std::cout<<"USER\tLINE\tTIME\tHOST\n";setutxent();struct utmpx*u;while((u=getutxent())!=nullptr){if(u->ut_type!=USER_PROCESS)continue;std::string name(u->ut_user,strnlen(u->ut_user,sizeof u->ut_user));std::string line(u->ut_line,strnlen(u->ut_line,sizeof u->ut_line));if(cmd=="usrs"){users.insert(name);continue;}std::time_t t=u->ut_tv.tv_sec;std::tm tm{};localtime_r(&t,&tm);char when[32]{};std::strftime(when,sizeof when,"%Y-%m-%d %H:%M",&tm);std::string host(u->ut_host,strnlen(u->ut_host,sizeof u->ut_host));std::cout<<name<<'\t'<<line<<'\t'<<when<<'\t'<<host<<"\n";}endutxent();if(cmd=="usrs"){for(const auto&x:users)std::cout<<x<<' ';std::cout<<"\n";}return 0;}
